select 'USUARIOS' tag, id::text k1, nome k2, (ativo||'|'||bloqueado||'|'||is_deleted)::text k3 from sigov.usuario where not is_deleted or id in (1,101,102) order by id;
select 'ETAPAS' tag, r.numero||' c'||a.ciclo||' n'||a.nivel k1, coalesce(a.aprovador_id::text,'NULL') k2, a.status||'/'||coalesce(a.causa_bloqueio,'-') k3 from sigov.compras_empresarial_aprovacao a join sigov.compras_empresarial_requisicao r on r.id=a.requisicao_id where a.tenant_id='b0000001-0000-4000-8000-000000000001' order by r.numero,a.ciclo,a.nivel,a.id;
select 'REQUISICOES' tag, r.numero k1, r.status k2, r.version::text||' total='||coalesce(r.valor_estimado::text,'0') k3 from sigov.compras_empresarial_requisicao r where r.tenant_id='b0000001-0000-4000-8000-000000000001' and not r.is_deleted order by r.numero;
select 'POLITICA' tag, p.id::text k1, p.nome||' ativo='||p.ativo k2, coalesce(nv.ordem,'-')||': '||coalesce(nv.limite::text,'-') k3 from sigov.compras_empresarial_aprovacao_politica p left join sigov.compras_empresarial_aprovacao_politica_nivel nv on nv.politica_id=p.id and not nv.is_deleted where p.tenant_id='b0000001-0000-4000-8000-000000000001' order by p.id,nv.ordem;
select 'PENDENCIAS' tag, p.tipo k1, p.status k2, left(p.titulo,60) k3 from sigov.pendencia_operacional p where p.tipo like 'APROVACAO%' order by p.id;
